"""Writes the prompt files of the documents round: eight directions, dark and light.
Usage: python3 prompts.py   (writes <slug>-<theme>.txt beside itself)"""
from pathlib import Path
R = Path(__file__).parent

HEAD = """UI design mockup of the project screen of an AI software factory console, in its existing "Mission control" design: a near-black blue room (dark) or a warm cream day version (light), thin-bordered instrument panels with small corner marks, cyan as the system colour, amber as the one signal that needs a person, monospace figures, everything exact and calm. Desktop browser viewport, 16:9, flat, no browser chrome, no device frame, the screen fills the whole image.

The shell is fixed and must look like this: a quiet top bar ("Factory console", the project "ai-software-factory-code", links "Board", "New task", "Projects", "Resources", "Costs", "Policy", "Alerts", a small moon-and-sun theme selector in a thin frame, "sebastian", "Log out"); under it the pulse band, one panel with the sentence "Two cards need your decision; #612's merge carries a migration." with an amber warning sign and a 3 px amber left rule, and under the sentence the instrument strip "● waiting on you | 3 working | 2 need you | €61.40 / €120.00 ▬▬▬▭▭ 51 % | GitHub: 1 open pull request | ▾"; then the main area: the chat on the left taking 40 percent of the width as the main region, with a narrow mono table of threads at its left edge ("Inbox" first with a small house mark, "Plan: the members page" with a cyan dot, "Session store: Postgres" as the open row, "Costs read: the date window") and the open thread's log and composer at its right (the box "Ask or tell the project…", "Send", small chips "/compact" "/new", and a small level button "assisted" under Send); and the board on the right taking 60 percent with its header row "Board", a small mono text box "Find: a word, #612, plan:558", "Wide view" and "?", and four columns: "Needs you 2" lit amber (a merge approval "Merge PR #612" with chips "high risk" "migration" and buttons "Approve", "Deny", "Split"; a question "#603 Which store for the session table?" with buttons "Postgres", "SQLite", "Ask the author"), "Queued 4", "In progress 5", "Done 8", each column head with a small ▾ at its right, the cards compact with a mono state row. No ticker at the foot."""

CONTENT = """What is new, and what this image is about: the member reads the project's documents inside this screen, Markdown files from the project's git repository, and moves between them by their links without leaving the chat. The open document is "docs/roadmap.md", rendered as readable text in the console's type at a comfortable measure, never as code: the heading "The project screen and members", then three numbered items as paragraphs, spelled exactly: "225. The lanes collapse: no card is filed undecided." with an underlined cyan link "the plan" inside the paragraph; "263. The backlog pull and the close-out." with the link "the plan" and the line "Where it stands: planned, the plan, not built."; "205. The main loop keeps the roadmap and its working notes." The document's head shows its path "docs/roadmap.md" in small mono, a two-way switch "Read | Edit" with Read pressed, a small "Open in Forgejo ↗" link, and a small "New document" button. The linked plan, where a direction shows it, is "docs/plans/2026-10-15-backlog-pull-and-close-out.md" with the heading "Plan: the backlog pull and the close-out". Where a direction shows the edit state, it is the same document as raw Markdown in a plain text area in mono, with a "Save as commit" button and the quiet line "Saved: 9e6bb40 on master · 14:12". The chat at the left stays as it is and stays usable: the member copies between the document and the chat."""

TAIL = """Legible UI text with exact spelling, nothing invented, no lorem ipsum. The pulse stays the loudest thing on the screen after the amber Needs you column; the chat stays the main region; the document is a quiet reading surface in the text colour, its links the only cyan in it, and the only loud marks are the ones the shell already has. Made by a top product design studio. Not a template, not a generic admin dashboard, not a code editor."""

D = [
 ("01-wiki-drawer", "Wiki drawer", """The drawer is open at the right edge over the board, 46 percent of the width, and the chat stays visible at the left. The drawer holds one document, the roadmap, rendered. Its head is one quiet row: at the left two small arrow buttons "‹" and "›" (back and forward, the forward one dimmed), then the path "docs/roadmap.md" in mono, then a small "Recent ▾" menu, then "Read | Edit", "Open in Forgejo ↗", and the drawer's × at the far right. Under the head a thin row of three small mono pins "roadmap" (pressed, cyan underline), "build plan", "backlog plan", and a faint "+ pin". Then the document. A link in the document opens its target in this same drawer, so there are no tabs. The board behind the drawer shows its Needs you column still visible at the left of the drawer."""),
 ("02-tabs", "Tabs", """The drawer is open at the right edge over the board, 46 percent of the width, and the chat stays visible at the left. Across the drawer's head runs a tab strip in the console's quiet style: tabs "#612 Merge PR" (a card, with its small amber dot), "roadmap" (the open tab, cyan underline), "backlog plan", "layers", and a small "+" at the strip's end; each tab has a tiny × on hover. Under the strip the document's own row: the path "docs/roadmap.md" in mono, "Read | Edit", "Open in Forgejo ↗", "New document". Then the rendered roadmap. A link in the document opens its target as a new tab. The strip is one line and the fourth tab is already cut with an ellipsis, which shows the strip's limit honestly."""),
 ("03-reader", "Reader", """The board is covered entirely by a reading pane that takes the board's full 60 percent width, with a 1 px cyan left rule, and the chat stays as it is at the left. The pane's head: a breadcrumb trail in small mono "roadmap › backlog plan › roadmap" showing the path the reader took, with the current one in the text colour and the earlier ones in the muted colour as links, then at the right "Read | Edit", "Open in Forgejo ↗", a small "Narrow" button that would shrink the pane back to the drawer's width, and ×. The document sits centred in the pane at a measure of about 70 characters with generous margins, the most comfortable read of the eight. Under the pane's head a thin line in the faint colour reads "Needs you: 2 · Merge PR #612 · #603 question" so the covered column is still one glance away, with a small "show board" link."""),
 ("04-split", "Split", """The drawer is open at the board's full 60 percent width over the board, and the chat stays at the left. The drawer is split into two equal panes by a hairline: the left pane holds the roadmap, the right pane holds the linked plan "Plan: the backlog pull and the close-out", each pane with its own small head (the path in mono, "Read | Edit"). A link clicked in the left pane opens its target in the right pane, so the source and the target are side by side. Over both panes one row: "Swap ⇄", "One pane", "Open in Forgejo ↗", "New document", ×. The left pane's link "the plan" on item 263 is shown in the pressed state (a faint cyan background) to say it is the one open at the right."""),
 ("05-docs-page", "Docs page", """The top bar has one more link, "Docs", shown as the current page, and the whole area under the top bar is the Docs page: no pulse band, no board. Three columns: at the left a narrow file tree in small mono ("docs/" open: "roadmap.md" as the selected row with a 2 px cyan left rule, "layers.md", "architecture.md", "plans/" open with "2026-10-15-backlog-pull-and-close-out.md", "2026-10-14-lane-collapse.md", "board/"); in the middle the document, rendered, with its head (the path, "Read | Edit", "Open in Forgejo ↗", "New document"); at the right the chat as a narrower column of about 30 percent with the thread table folded to a "Session store: Postgres ▾" title and the log and composer under it, so the chat follows the member to this page."""),
 ("06-chat-pane", "Chat pane", """The board is untouched and no drawer is open. The document opens inside the chat column itself: the chat's log is pushed up into the top third, and under it a document pane with a 1 px cyan top rule takes the lower two thirds of the chat column, above the composer, holding the roadmap rendered with its own small head (the path "docs/roadmap.md" in mono, "Read | Edit", "Open in Forgejo ↗", a small "▲" to fold it). In the chat's head, beside the thread title "Session store: Postgres", three small mono chips "roadmap" (pressed), "build plan", "backlog plan" as the pins. The composer sits under the document pane, so the member types with the document right above. The thread table at the chat's left edge stays."""),
 ("07-peek", "Peek", """The drawer is open at the right edge over the board, 46 percent of the width, and the chat stays at the left. The drawer holds the roadmap rendered, with the plain head (the path in mono, a "Recent ▾" menu, "Read | Edit", "Open in Forgejo ↗", "New document", ×) and no back or forward arrows. The pointer rests on the link "the plan" of item 263, and a popover panel in the console's panel style floats beside it: the title "Plan: the backlog pull and the close-out" in the text colour, its first paragraph in the muted colour, four lines, cut with an ellipsis, and a small cyan "open ›" at the popover's foot. The link under the pointer carries a cyan underline. The idea: most jumps are a glance, so a glance needs no navigation; a click opens the target in place."""),
 ("08-tree-rail", "Tree rail", """The drawer is open at the right edge over the board, 46 percent of the width, and the chat stays at the left. Inside the drawer, at its left edge, a narrow rail about 180 px wide in small mono lists the document roots as a tree: "roadmap.md" as the selected row with a 2 px cyan left rule, "layers.md", "architecture.md", "plans/" open with "2026-10-15-backlog-pull…", "2026-10-14-lane-collapse…", "board/" folded; a small "‹" at the rail's top folds it to a thin strip. Right of the rail the document with its head (the path, "Read | Edit", "Open in Forgejo ↗", "New document", ×) and the rendered roadmap. A link in the document opens its target in the same place and selects its row in the rail."""),
]
for slug, name, body in D:
    for theme in ("dark", "light"):
        t = "Dark theme." if theme == "dark" else "Light theme: the cream day version of the same design, dark navy text on warm off-white panels, the same cyan and amber."
        (R / f"{slug}-{theme}.txt").write_text(f"{HEAD}\n\n{CONTENT}\n\nDirection \"{name}\": {body} {t}\n\n{TAIL}\n")
print(len(D) * 2, "prompts")
